contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint amount, uint am, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        c.Put{value: amount}(lockTime); if (__ESBMC_reverted()) return;
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        (uint unlockBefore, uint balBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        require(block.timestamp > unlockBefore);
        require(balBefore >= am);
        require(balBefore >= minSum);

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        (uint unlockAfter, uint balAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted || (balAfter == balBefore - am && unlockAfter == unlockBefore));
    }
    receive() external payable {}
}

