pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 lockTime, uint256 amount, uint256 am, uint256 minSum) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.Put{value: amount}(lockTime) {} catch { return; }
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 unlockBefore;
        uint256 balBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockBefore = __r0; balBefore = __r1; } catch { return; }
        vm.assume(block.timestamp > unlockBefore);
        vm.assume(balBefore >= am);
        vm.assume(balBefore >= minSum);
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 unlockAfter;
        uint256 balAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockAfter = __r0; balAfter = __r1; } catch { return; }
        assertTrue(reverted || (balAfter == balBefore - am && unlockAfter == unlockBefore));
    }

    function testFuzz_run(uint256 lockTime, uint256 amount, uint256 am, uint256 minSum) public {
        _run(lockTime, amount, am, minSum);
    }

    receive() external payable {}
}
